// fetch polyfill for n8n (with error logging)
const _h = this.helpers;
const _fetchLog = [];
async function fetch(url, opts = {}) {
  const body = opts.body ? JSON.parse(opts.body) : undefined;
  const shortUrl = url.replace(/key=[^&]+/, 'key=***').substring(0, 80);
  try {
    const resp = await _h.httpRequest({ method: opts.method || 'GET', url, headers: opts.headers || {}, body, json: true, returnFullResponse: true });
    _fetchLog.push('OK ' + (resp.statusCode||200) + ' ' + shortUrl);
    return { ok: true, status: resp.statusCode || 200, json: async () => resp.body };
  } catch(e) {
    const st = e.response?.statusCode || e.statusCode || 500;
    const msg = e.response?.body?.error?.message || e.message || 'unknown';
