const src = $input.first().json;
const body = src.body || src;
let existing = body.existing_data || {};
if (typeof existing === 'string') { try { existing = JSON.parse(existing); } catch(e){} }

const action = body.action || body.regenerate_target || "";
const mode = body.mode || (action ? "regenerate" : "new");

const availableCategories = body.available_categories || existing.available_categories || "Technology, Business, Startups, Artificial Intelligence";

const imgAspect = body.image_aspect_ratio || existing.image_aspect_ratio || "16:9 widescreen landscape";
const imgMood = "dramatic, dark moody tones, deep shadows, atmospheric";
const imgNegative = "no text, no logos, no watermarks, no borders, no frames";
const imgExtra = "Add a subtle dark gradient overlay at the bottom. Color palette: deep blues, dark greens, grey tones.";

const origText = existing.orig_text || body.text || existing.text || "";

// Extract ai_config from body (sent by WordPress plugin)
const ai_config = body.ai_config || existing.ai_config || {
  gemini_api_key: body.gemini_api_key || "",
  gemini_model: "gemini-2.5-flash",
  gemini_image_model: "gemini-2.5-flash",
  gemini_text: true, gemini_image: true,
