// callTextAI — 3-level fallback: Gemini → OpenAI → OpenRouter
// ═══════════════════════════════════════════════════════════════
async function callTextAI(prompt, cfg, genConfig) {
  const providers = [];
  if (cfg.gemini_text && cfg.gemini_api_key) {
    const m = cfg.gemini_model;
    if (m.includes('/')) {
      providers.push({type:'or', model:m, key:cfg.openrouter_api_key||cfg.gemini_api_key, level:1});
    } else {
      providers.push({type:'gemini', model:m, key:cfg.gemini_api_key, level:1});
    }
  }
  if (cfg.openai_text && cfg.openai_api_key && cfg.openai_model) {
    providers.push({type:'openai', model:cfg.openai_model, key:cfg.openai_api_key, level:2});
  }
  if (cfg.deepseek_text && cfg.deepseek_api_key && cfg.deepseek_model) {
    providers.push({type:'deepseek', model:cfg.deepseek_model, key:cfg.deepseek_api_key, level:3});
  }
  if (cfg.openrouter_text && cfg.openrouter_api_key && cfg.openrouter_model) {
    providers.push({type:'or', model:cfg.openrouter_model, key:cfg.openrouter_api_key, level:4});
  }
  const maxR = cfg.retry_count || 3;
  const delayMs = (cfg.retry_delay || 3) * 1000;
  const wait = ms => new Promise(r => setTimeout(r, ms));
  const safety = [{category:'HARM_CATEGORY_HARASSMENT',threshold:'BLOCK_NONE'},{category:'HARM_CATEGORY_HATE_SPEECH',threshold:'BLOCK_NONE'},{category:'HARM_CATEGORY_SEXUALLY_EXPLICIT',threshold:'BLOCK_NONE'},{category:'HARM_CATEGORY_DANGEROUS_CONTENT',threshold:'BLOCK_NONE'}];
  const gc = genConfig || {temperature:0.5, maxOutputTokens:8192};
  for (const p of providers) {
    for (let a = 1; a <= maxR; a++) {
      try {
        let url, headers, reqBody;
        if (p.type === 'gemini') {
          url = `https://generativelanguage.googleapis.com/v1beta/models/${p.model}:generateContent?key=YOUR_TOKEN_HERE
          headers = {'Content-Type':'application/json'};
          reqBody = JSON.stringify({contents:[{parts:[{text:prompt}]}], generationConfig:gc, safetySettings:safety});
        } else {
          url = p.type === 'openai' ? 'https://api.openai.com/v1/chat/completions' : (p.type === 'deepseek' ? 'https://api.deepseek.com/chat/completions' : 'https://openrouter.ai/api/v1/chat/completions');
          headers = {'Authorization':`Bearer ${p.key}`, 'Content-Type':'application/json'};
          if (p.type === 'or') headers['HTTP-Referer'] = 'https://YOURURL';
          reqBody = JSON.stringify({model:p.model, messages:[{role:'user',content:prompt}], temperature:gc.temperature||0.5, max_tokens:gc.maxOutputTokens||4096});
        }
        const res = await fetch(url, {method:'POST', headers, body:reqBody});
        if (res.ok) {
          const data = await res.json();
          const text = p.type === 'gemini'
            ? (data?.candidates?.[0]?.content?.parts?.[0]?.text || '').trim()
            : (data?.choices?.[0]?.message?.content || '').trim();
          if (text) return {text, provider:p.type, model:p.model, level:p.level, attempts:a};
        }
        const st = res.status;
        if (![429,500,502,503].includes(st)) break;
        if (a < maxR) await wait(delayMs);
      } catch(e) { if (a >= maxR) break; await wait(delayMs); }
    }
  }
  return {text:'', provider:'none', model:'none', level:0, attempts:0, error:'All providers failed'};
}
