async function callImageAI(imagePrompt, cfg) {
  const providers = [];
  if (cfg.gemini_image && cfg.gemini_api_key && cfg.gemini_image_model) {
    providers.push({type:'gemini', model:cfg.gemini_image_model, key:cfg.gemini_api_key, level:1});
  }
  if (cfg.openai_image && cfg.openai_api_key && cfg.openai_image_model) {
    providers.push({type:'openai', model:cfg.openai_image_model, key:cfg.openai_api_key, level:2});
  }
