          const url = `https://generativelanguage.googleapis.com/${apiBase}/models/${p.model}:generateContent?key=YOUR_TOKEN_HERE
          const body = JSON.stringify({contents:[{parts:[{text:imagePrompt}]}], generationConfig:{responseModalities:['IMAGE']}, safetySettings:safety});
          const res = await fetch(url, {method:'POST', headers:{'Content-Type':'application/json'}, body});
          if (res.ok) {
            const data = await res.json();
            const parts = data?.candidates?.[0]?.content?.parts || [];
            for (const part of parts) {
              if (part.inlineData) return {base64:part.inlineData.data, mime:part.inlineData.mimeType||'image/png', provider:'gemini', model:p.model, level:p.level, attempts:a};
            }
          }
          if (![429,500,502,503].includes(res.status)) break;
